import {AUTHORITY_TYPES,DEMO_ACCOUNTS,DEMO_PASSWORD,SESSION_KEY,authenticateDemo,startSession,activeAuthority,selectAuthority,allowed,requirePermission,serializeSession,restoreSession} from './auth.mjs';
import {workBuckets,nextAction,recordChanges,focusedRelations,programFamilies} from './operations.mjs';
import {scopeRecords,searchEntities,searchRelations,relations} from './explorer.mjs';
import {TYPES,PEOPLE,STATUS,seed,find,live,active,blockers,eligible,canReview,nextReviewers,matchRules,saveDraft,submit,decide,amend,allEvents,addEvent} from './domain.mjs';
function analytics(){
 const rows=data.records.filter(r=>inProgram(r,ui.analyticsProgram));const total=rows.length,approved=rows.filter(live).length,pending=rows.filter(r=>r.status==='In review').length;const times=rows.filter(r=>r.status==='Approved').map(r=>{const submitted=r.history.filter(e=>e.action==='Submitted for approval').sort((a,b)=>b.at.localeCompare(a.at))[0],end=r.history.filter(e=>e.action==='Approved').sort((a,b)=>b.at.localeCompare(a.at))[0];return submitted&&end?Math.max(0,(new Date(end.at)-new Date(submitted.at))/3600000):null}).filter(n=>n!==null);const avg=times.length?(times.reduce((a,b)=>a+b,0)/times.length).toFixed(1):'—';
 const statuses=['Approved','In review','Draft','Changes requested','Rejected'],colors=['#abc2b0','#e3c897','#a6d7ed','#dab0ba','#ba8c9a'];let start=0;const stops=statuses.map((s,i)=>{const n=rows.filter(r=>r.status===s).length;let before=start;start+=n/Math.max(1,total)*100;return `${colors[i]} ${before}% ${start}%`}).join(',');
 const days=Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()-(6-i));const key=day.toISOString().slice(0,10);return {label:day.toLocaleDateString('en-GB',{day:'numeric',month:'short'}),submitted:rows.reduce((n,r)=>n+r.history.filter(e=>e.action==='Submitted for approval'&&e.at.slice(0,10)===key).length,0),approved:rows.reduce((n,r)=>n+r.history.filter(e=>e.action==='Approved'&&e.at.slice(0,10)===key).length,0)};});const max=Math.max(1,...days.map(d=>Math.max(d.submitted,d.approved)));
 return `${heading('Workspace insights','Understand flow, spot bottlenecks and see where the work is moving.',`<select class="filter-select" data-change="analyticsProgram" aria-label="Analytics program">${programOptions(true,ui.analyticsProgram)}</select>`)}<div class="stats">${stat('Approved records',total?Math.round(approved/total*100)+'%':'—',`${approved} of ${total} records have an active version`,'circlecheck','green')}${stat('Average approval time',avg==='—'?avg:avg+'h',`${times.length} completed review cycles`,'clock','amber')}${stat('In the review flow',num(pending),'Open requests in this view','layers','')}${stat('Returned for changes',num(rows.filter(r=>r.status==='Changes requested').length),'Requests needing maker attention','edit','blue')}</div><div class="analytics-grid"><section class="card"><div class="card-head"><h2>The rhythm of your workflow</h2><span class="tag">Last 7 days</span></div><div class="card-body"><div class="chart-key"><span><i class="dot" style="background:#76cbed"></i>Submitted</span><span><i class="dot" style="background:#abc2b0"></i>Approval decisions</span></div><svg class="chart-svg" viewBox="0 0 580 230" role="img" aria-label="Requests submitted and approval decisions by day">${[0,1,2,3].map(i=>`<line x1="35" y1="${25+i*50}" x2="570" y2="${25+i*50}" stroke="#e5f1f7"/><text x="9" y="${29+i*50}">${Math.round(max*(1-i/3))}</text>`).join('')}${days.map((d,i)=>`<rect x="${52+i*73}" y="${175-d.submitted/max*150}" width="17" height="${d.submitted/max*150}" rx="3" fill="#76cbed"><title>${d.label}: ${d.submitted} submissions</title></rect><rect x="${73+i*73}" y="${175-d.approved/max*150}" width="17" height="${d.approved/max*150}" rx="3" fill="#abc2b0"><title>${d.label}: ${d.approved} approval decisions</title></rect><text x="${72+i*73}" y="205" text-anchor="middle">${d.label}</text>`).join('')}</svg><div class="metrics-note">Calculated from the workspace audit events. Multiple reviewers can approve a single request.</div></div></section><section class="card"><div class="card-head"><h2>Where things stand</h2>${I('chart','small-icon')}</div><div class="card-body"><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${total?stops:'#eee 0% 100%'})"><div class="donut-center"><strong>${total}</strong><span>total records</span></div></div><div class="donut-legend">${statuses.slice(0,4).map((s,i)=>`<div class="between"><span><i class="dot" style="background:${colors[i]}"></i>${s==='Changes requested'?'Returned':s}</span><strong>${rows.filter(r=>r.status===s).length}</strong></div>`).join('')}</div></div><div class="metrics-note">Current request statuses. An approved version may stay active during a proposed change.</div></div></section></div><div class="lower-grid"><section class="card"><div class="card-head"><h2>Reviewer workload</h2><span class="tag">Ready to act</span></div><div class="card-body">${PEOPLE.filter(p=>p.role==='Checker').map(p=>{const n=rows.filter(r=>canReview(r,p.id)).length;return `<div class="work-row" style="padding:16px 0">${av(p.id)}<div class="work-info"><div class="strong small">${p.name}</div><div class="record-sub">${p.title}</div></div><strong>${n}</strong><span class="tiny muted">requests</span></div>`}).join('')}${textbtn('Open approval inbox','nav','arrow','data-page="approvals"')}</div></section><section class="card"><div class="card-head"><h2>Records by family</h2><span class="tag">Current view</span></div><div class="card-body bar-chart">${['Partner setup','Products & releases','Shared configurations'].map(g=>{const n=rows.filter(r=>TYPES[r.type].group===g).length;return `<div class="bar-row"><span>${g}</span><div class="bar-track"><div class="bar-fill" style="width:${n/Math.max(total,1)*100}%"></div></div><strong>${n}</strong></div>`}).join('')}</div></section></div><p class="metrics-note">Illustrative demo records. These metrics update as you create, submit and review records.</p>`;
}
function auditPage(){const events=filteredEvents();return `${heading('Audit trail','A chronological history of records, relationships and decisions.',btn('Export history','export-audit','download'))}<div class="filters"><div class="filter-input">${I('search','small-icon')}<input id="audit-search" data-input="search" value="${esc(ui.q)}" aria-label="Search audit history" placeholder="Search record, person or decision…"></div><select class="filter-select" data-change="auditAction" aria-label="Audit action"><option value="all">All actions</option>${[...new Set(allEvents(data).map(e=>e.action))].sort().map(s=>`<option ${ui.auditAction===s?'selected':''}>${s}</option>`).join('')}</select><select class="filter-select" data-change="auditPerson" aria-label="Audit actor"><option value="all">All people</option>${PEOPLE.map(p=>`<option value="${p.id}" ${ui.auditPerson===p.id?'selected':''}>${p.name}</option>`).join('')}</select>${ui.auditRecord?btn('Clear record filter','clear-audit','close','sm'):''}</div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>WHEN · IST</th><th>WHO</th><th>WHAT HAPPENED</th><th>RECORD</th><th>CONTEXT</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td class="muted" style="font-size:10px">${date(e.at)}</td><td><div class="flex gap8">${av(e.actor,'tinyavatar')}<span>${P(e.actor).name}</span></div></td><td><span class="flex gap8">${I(e.action.includes('Approved')?'circlecheck':e.action.includes('Submitted')?'arrow':e.action==='Changes requested'?'edit':'audit','small-icon')}${esc(e.action)}</span></td><td>${e.recordId?recordButton(find(data,e.recordId)):'Approval policies'}<div class="record-sub">${esc(e.code||'Workspace policy')} ${e.version?'· v'+e.version:''}</div></td><td class="muted" style="max-width:290px;white-space:normal;font-size:10px">${esc(e.detail)}</td><td>${e.recordId?`<button class="iconbtn" data-action="record" data-id="${e.recordId}" data-tab="history" aria-label="View record history">${I('chevron','small-icon')}</button>`:''}</td></tr>`).join('')}</tbody></table>${events.length?'':empty('No events match this view','Try a different filter or search term.','search')}</div><div class="table-footer">${events.length} events · Demo history is stored locally. Production requires a server-enforced, append-only audit log.</div></div>`}
function filteredEvents(){return allEvents(data).filter(e=>(ui.auditAction==='all'||e.action===ui.auditAction)&&(ui.auditPerson==='all'||e.actor===ui.auditPerson)&&(!ui.auditRecord||e.recordId===ui.auditRecord)&&(!ui.q||(e.recordName+' '+e.detail+' '+e.action+' '+P(e.actor).name).toLowerCase().includes(ui.q.toLowerCase())))}
function policies(){return `${heading('Approval policies','Set a review route for each entity type.',btn('How approvals work','help','help'))}${note('Configure one or two named reviewers. Sequential reviews happen in order; parallel reviews require everyone selected. Policy changes apply to <strong>new or resubmitted drafts</strong>. In-flight reviews keep their captured route.','','shield')}${!can('create')?note('Policy controls are read-only under your selected authority. The Maker authority includes policy administration in this prototype. A production workspace would use a separate administrator permission.','amber','lock'):''}<div class="policy-grid">${Object.entries(TYPES).map(([t,v])=>{const p=data.policies[t];return `<section class="card policy-card"><div class="between"><div class="flex gap10" style="gap:10px">${ti(t)}<h3>${v.label}</h3></div><span class="tag">${p.reviewers.length} reviewer${p.reviewers.length===1?'':'s'}</span></div><select class="policy-select" data-change="policy-mode" data-type="${t}" aria-label="${v.label} approval mode" ${!can('create')?'disabled':''}><option value="sequential" ${p.mode==='sequential'?'selected':''}>Sequential · Reviewers act in order</option><option value="parallel" ${p.mode==='parallel'?'selected':''}>Parallel · All reviewers act together</option></select>${PEOPLE.filter(p=>p.role==='Checker').map((person,i)=>`<label class="checkrow"><input type="checkbox" data-change="policy-reviewer" data-type="${t}" value="${person.id}" ${p.reviewers.includes(person.id)?'checked':''} ${!can('create')?'disabled':''}>${av(person.id,'tinyavatar')} ${person.name} <span style="margin-left:auto" class="tiny muted">${!p.reviewers.includes(person.id)?'Not assigned':p.mode==='sequential'?'Stage '+(p.reviewers.indexOf(person.id)+1):'Required reviewer'}</span></label>`).join('')}</section>`}).join('')}</div><div class="policy-note">Changes save immediately and appear in the audit trail. At least one reviewer is required. The maker cannot review their own request.</div>`}
function setup(){
 const p=find(data,ui.program)||data.records.find(r=>r.type==='program'),org=find(data,p.refs.org),families=programFamilies(data,p.id);
 return `${heading('Program workspace','Build out a program at your own pace. Every family can contain many records.',`<select class="filter-select" data-change="program" aria-label="Workspace program">${programOptions()}</select>`)}
 <section class="program-context"><div><div class="context-breadcrumb">${recordButton(org)} ${I('chevron','small-icon')} Partner program</div><h2>${esc(p.name)}</h2><p>${esc(p.description||'Manage every brand, product and release connected to this program.')}</p><div class="flex gap8">${badge(p)}<span class="tag">${p.code}</span><span class="small muted">${families.reduce((n,f)=>n+f.rows.length,0)} connected records</span></div></div><div class="stack">${btn('Program details','record','eye','',`data-id="${p.id}"`)}${btn('Trace connections','program-map','map','',`data-id="${p.id}"`)}</div></section>
 ${!live(p)?note('This program needs approval before you can submit its brands, products or releases. You can prepare drafts now.','amber','clock'):''}
 <div class="family-section-heading"><h2>Build your program</h2><span class="muted small">Expand a family to see every record and its parent.</span></div><div class="family-grid">${families.map(f=>`<section class="card family-card"><div class="between"><div class="flex gap12">${ti(f.type)}<h3>${f.label}</h3></div><span class="family-total">${f.rows.length}</span></div><p>${TYPES[f.type].hint}</p><div class="family-counts"><span><i class="dot"></i>${f.active} active</span><span>${f.pending} in review</span><span>${f.rows.length-f.rows.filter(r=>r.status==='Approved'||r.status==='In review').length} other requests</span></div><div class="family-actions">${can('create')?btn('Add '+TYPES[f.type].short.toLowerCase(),'create-child','plus','sm',`data-type="${f.type}" data-parent="${p.id}"`):textbtn('Browse records','browse-type','arrow',`data-type="${f.type}"`)}</div><details class="family-records"><summary>View all ${f.rows.length} records ${I('down','small-icon')}</summary>${f.rows.map(r=>{const parentKey=TYPES[r.type].deps.find(k=>k!=='program'),parent=find(data,r.refs[parentKey]);return `<div class="family-record"><div>${recordButton(r)}<span class="record-sub">${parent?esc(active(parent).name):'Directly under '+esc(p.name)}</span></div>${badge(r)}</div>`}).join('')||'<p>No records yet. Add the first when you are ready.</p>'}</details></section>`).join('')}</div>
 <section class="shared-strip"><div>${I('sliders')}<h3>Shared configurations</h3><p>Create BINs, ACE option sets, CPCs and attribute rules independently. Reuse them across programs.</p></div>${btn('Open configurations','nav','arrow','','data-page="configurations"')}</section>`;
}

function openRecord(id,tab='overview'){
 const r=find(data,id);if(!r)return;
 if(wizard)rememberWizard();
 if(drawer&&drawer.id!==id){captureReviewNote();recordTrail.push({...drawer});}
 else if(!drawer){recordTrail.length=0;focusBefore=document.activeElement;}
 drawer={id,tab};wizard=null;renderDrawer();
}

function closeOverlay(){
 if(wizard)rememberWizard();captureReviewNote();
 document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';drawer=null;wizard=null;recordTrail.length=0;focusBefore?.focus?.();
}

function mountOverlay(html){document.getElementById('overlay-root').innerHTML=html;document.body.style.overflow='hidden';requestAnimationFrame(()=>document.querySelector('#overlay-root [data-autofocus], #overlay-root button, #overlay-root input')?.focus());}
function renderDrawer(){
 const r=find(data,drawer.id);if(!r)return;
 const editable=can('create')&&user===r.owner&&['Draft','Changes requested'].includes(r.status),review=drawer.tab==='approval';
 const tabs=[['overview',r.published?'Proposed details':'Details'],['approval','Review request'],...(r.published?[['active','Active v'+r.published.version]]:[]),['history','History']];
 mountOverlay(`<div class="overlay" data-overlay="true"><section class="drawer record-workspace ${review?'review-workspace':''}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><div>${recordTrail.length?`<button class="back-record" data-action="record-back">← Back to ${esc(find(data,recordTrail.at(-1).id)?.name||'previous record')}</button>`:''}<div class="flex gap8">${ti(r.type)}<span class="eyebrow">${TYPES[r.type].label} · ${r.code}</span></div><h2 id="drawer-title">${esc(drawer.tab==='active'?r.published.name:r.name)}</h2><div class="flex gap8">${badge(drawer.tab==='active'?'Approved':r)}<span class="tag">${drawer.tab==='active'?'Active v'+r.published.version:(r.published?'Proposed':'Request')+' v'+r.version}</span>${r.published&&drawer.tab!=='active'?'<span class="active-version">Active v'+r.published.version+' remains available</span>':''}</div></div><button class="iconbtn" data-action="close" aria-label="Close record">${I('close')}</button></div><div class="tabs">${tabs.map(([k,label])=>`<button class="tab ${drawer.tab===k?'active':''}" data-action="detail-tab" data-id="${k}">${label}${k==='history'?`<span class="count">${r.history.length}</span>`:''}</button>`).join('')}</div><div class="drawer-main">${drawer.snapshotNotice?note(esc(drawer.snapshotNotice),'amber','info'):''}${drawer.tab==='history'?historyView(r):review?reviewWorkspace(r):drawer.tab==='active'?recordOverview({...r.published,status:'Approved',history:r.history}):recordOverview(r)}</div><div class="drawer-footer"><span class="small muted">${av(r.owner,'tinyavatar')} Made by ${P(r.owner).name}</span><div class="flex gap8">${editable?btn('Edit draft','edit-record','edit','primary',`data-id="${r.id}"`):can('create')&&user===r.owner&&(r.status==='Approved'||r.status==='Rejected'&&r.published)?btn(r.status==='Rejected'?'Start a new change':'Propose a change','amend','edit','primary',`data-id="${r.id}"`):canActOnReview(r)&&!review?btn('Review request','detail-tab','circlecheck','primary','data-id="approval"'):btn('Close','close')}</div></div></section></div>`);
}
function reviewWorkspace(r){
 const changes=recordChanges(r),children=new Set(focusedRelations(data,r.id,true).outgoing.map(e=>e.to.id));
 const labels={name:'Name',description:'Description',refs:'Parent connections',region:'Region',channel:'Channel',segment:'Segment',category:'Category',value:'Configuration value',rule:'Matching rule'};
 const captured=['In review','Approved','Rejected'].includes(r.status);
 const refs=(captured?r.submittedRefs:null)||Object.fromEntries(Object.entries(r.refs).map(([key,id])=>{const p=active(find(data,id)||{});return [key,p]}));
 return `<div class="review-layout"><div class="review-evidence"><div class="review-intro"><span class="eyebrow">${r.published?'CHANGE REQUEST':'NEW RECORD REQUEST'}</span><h3>${r.published?'What will change':'What is being created'}</h3><p>${r.published?'Compare the active record with this proposal before deciding.':'Review the business details and approved references below.'}</p></div>${r.status==='Changes requested'?note(esc(r.history.find(e=>e.action==='Changes requested')?.detail||'The maker needs to address reviewer feedback.'),'amber','edit'):''}
 <div class="comparison-table"><div class="comparison-head"><span>Field</span>${r.published?`<span>Active v${r.published.version}</span>`:''}<span>${r.published?'Proposed v'+r.version:'Submitted value'}</span></div>${changes.map(c=>`<div class="comparison-row ${r.published?'amendment':''}"><strong>${labels[c.field]||c.field}</strong>${r.published?`<div class="before-value">${esc(readable(c.before))}</div>`:''}<div class="after-value">${esc(readable(c.after))}</div></div>`).join('')||'<div class="comparison-empty">No business fields have changed.</div>'}</div>
 <div class="section-heading">Approved references <span class="tag">${Object.keys(refs).length}</span></div><p class="form-hint">${captured&&r.submittedRefs?'Versions captured when this request was submitted.':'Current parent versions. References are captured on submission.'}</p>${Object.entries(refs).map(([type,p])=>p.id?`<button class="ref-card" data-action="captured-record" data-id="${p.id}" data-version="${p.version}">${ti(type)}<span><span class="ref-label">${TYPES[type].label}</span><span class="ref-name" style="display:block">${esc(p.name)}</span></span><span class="tag" style="margin-left:auto">v${p.version}</span>${I('external','small-icon')}</button>`:'').join('')||note('Created independently. This record has no required parents.','','layers')}
 ${r.type==='release'?`<div class="section-heading">Attributes in this request</div>${(captured?(r.status==='Approved'?r.attributes:r.proposedAttributes)||[]:matchRules(data,r).matches.map(m=>({id:m.rule.id,version:m.rule.version,key:m.rule.rule.key,value:m.rule.rule.output}))).map(a=>`<div class="attribute-match"><strong>${esc(a.key)} → ${esc(a.value)}</strong><div class="why">${captured?'Captured':'Current'} rule v${a.version} · ${find(data,a.id)?btn('Inspect rule','captured-record','external','sm',`data-id="${a.id}" data-version="${a.version}"`):''}</div></div>`).join('')||'<p class="small muted">No attributes matched at submission.</p>'}`:''}
 <div class="impact-note">${I('map')}<div><strong>${children.size} active downstream ${children.size===1?'entity':'entities'}</strong><p>${r.published?'Existing records retain their captured submission versions. Reparenting is blocked while active children depend on this record.':'This record becomes available for new connections after all required reviewers approve.'}</p></div></div>${textbtn('View the complete audit history','detail-tab','audit','data-id="history"')}</div><aside class="review-decision"><div class="eyebrow">APPROVAL ROUTE</div><h3>${r.review.mode==='parallel'?'Everyone must approve':'Reviewers act in order'}</h3>${approvalDetail(r)}</aside></div>`;
}

function recordOverview(r){const parents=Object.entries(r.refs).map(([key,id])=>({key,r:find(data,id)})).filter(x=>x.r);const children=data.records.filter(c=>Object.values(c.refs).includes(r.id));const childTypes=Object.keys(TYPES).filter(t=>TYPES[t].deps.includes(r.type));let html=`<p style="font-size:12px;color:#647c8b">${esc(r.description||'No description added yet.')}</p><div class="detail-grid"><div><div class="detail-label">OWNER</div><div class="detail-value">${P(r.owner).name}</div></div><div><div class="detail-label">LAST UPDATED</div><div class="detail-value" style="font-size:11px">${date(r.updatedAt)}</div></div><div><div class="detail-label">REGION</div><div class="detail-value">${esc(r.region||'India')}</div></div><div><div class="detail-label">REVIEW MODE</div><div class="detail-value">${r.review.mode==='parallel'?'Parallel · all selected reviewers':'Sequential · in order'}</div></div></div>`;
 if(parents.length)html+=`<div class="section-heading">Connected parent records <span class="tiny muted">${parents.length} connections</span></div>${parents.map(({key,r:p})=>`<button class="ref-card" data-action="record" data-id="${p.id}">${ti(p.type)}<span><span class="ref-label" style="display:block">${TYPES[key].label}</span><span class="ref-name">${esc(active(p).name)}</span></span>${badge(live(p)?'Approved':p.status)}</button>`).join('')}`;
 else html+=note('This record is created independently. Its approved version can be reused across multiple connections.','','layers');
 if(r.type==='release'){html+=`<div class="detail-grid">${['channel','segment','category'].map(k=>`<div><div class="detail-label">${k.toUpperCase()}</div><div class="detail-value">${esc(r[k])}</div></div>`).join('')}</div><div class="section-heading">${r.status==='Approved'?'Approved attribute snapshot':r.status==='In review'?'Attribute snapshot being reviewed':'Attribute match preview'}</div>`;if(['Approved','In review'].includes(r.status)){html+=(r.status==='Approved'?(r.attributes||[]):(r.proposedAttributes||[])).map(m=>`<div class="attribute-match"><div class="strong small">${esc(m.key)} · ${esc(m.value)}</div><div class="why">Captured rule version ${m.version} at submission. ${find(data,m.id)?recordButton(find(data,m.id),'View source rule'):''}</div></div>`).join('')||note('No attributes were matched when this release was submitted.');html+=`<div class="section-heading">Current rules preview</div>`;}html+=attributePreview(r);}
 if(r.type==='attribute'&&r.rule)html+=`<div class="section-heading">When this matches…</div><div class="attribute-match"><div class="strong small">${esc(r.rule.field)} equals “${esc(r.rule.value)}”</div><div class="why">Apply ${esc(r.rule.key)} = ${esc(r.rule.output)}</div><div class="attribute-output">Priority ${r.rule.priority} · Higher priority wins</div></div>${note('Equal-priority rules with different values for the same attribute block submission. Existing approved releases retain their captured rule versions.','','info')}`;
 if(r.value)html+=`<div class="section-heading">Configuration value</div><div class="callout">${esc(r.value)}</div>`;
 if(r.type==='mapping')html+=note('This approval authorises the connections shown above. The same configuration may be reused in other, independently approved brand mappings.','','link');
 html+=`<div class="section-heading">Built on this record <span class="tag">${children.length} children</span></div>${children.map(c=>`<button class="ref-card" data-action="record" data-id="${c.id}">${ti(c.type)}<span><span class="ref-label" style="display:block">${TYPES[c.type].label}</span><span class="ref-name">${esc(c.name)}</span></span>${badge(c)}</button>`).join('')||`<p class="small muted">${childTypes.length?'The next connections will appear here.':'This is an endpoint in the current model.'}</p>`}`;
 if(childTypes.length&&can('create'))html+=`<div class="section-heading">Create another connection</div><div class="pills">${childTypes.map(t=>`<button class="pill" data-action="create-child" data-type="${t}" data-parent="${r.id}" ${!live(r)?'disabled title="Approve this parent first"':''}>${I('plus','small-icon')} ${TYPES[t].short}</button>`).join('')}</div>`;
 html+=`<div class="divider"></div>${textbtn('View this record in the audit trail','record-audit','audit',`data-id="${r.id}"`)}`;return html;}
function attributePreview(r){const result=matchRules(data,r);return `${result.conflicts.length?`<div class="error">Conflicting rules for ${result.conflicts.map(esc).join(', ')}. Adjust the rule priorities or matching conditions before submission.</div>`:''}${result.evaluated.map(m=>m.matched?`<div class="attribute-match"><div class="between"><span class="strong small">${esc(m.rule.name)}</span>${I('circlecheck','small-icon')}</div><div class="why">Because ${esc(m.rule.rule.field)} is “${esc(r[m.rule.rule.field])}” · Rule v${m.rule.version}</div><div class="attribute-output">${esc(m.rule.rule.key)} → ${esc(m.rule.rule.output)} ${result.matches.some(x=>x.rule.id===m.rule.id)?'<span class="tag" style="margin-left:5px">Selected</span>':'<span class="tag" style="margin-left:5px">Lower priority or conflict</span>'}</div></div>`:`<div class="unmatched">${esc(m.rule.name)} · No match: ${esc(m.rule.rule.field)} must equal “${esc(m.rule.rule.value)}”.</div>`).join('')||note('No approved attribute rules exist yet. Create and approve a rule in Shared configurations.','','sliders')}`}
function approvalDetail(r){let html=note(r.review.mode==='parallel'?'Everyone selected can review at the same time. All reviewers must approve.':'Each reviewer acts after the previous stage is approved. Every stage must pass.','','shield');html+=r.review.reviewers.map((id,i)=>{const d=r.review.decisions[id],ready=canReview(r,id),done=d?.action==='approve';return `<div class="stage-card ${done?'done':ready?'current':''}"><div class="between"><div class="flex gap12">${av(id)}<div><div class="stage-label">${r.review.mode==='parallel'?'REVIEWER '+(i+1):'STAGE '+(i+1)}</div><div class="strong small" style="margin-top:5px">${P(id).name}</div><div class="muted" style="margin-top:3px">${P(id).title}</div></div></div>${done?badge('Approved'):d?badge(d.action==='return'?'Changes requested':'Rejected'):`<span class="tag">${ready?'Ready to review':r.status==='Draft'?'On submission':'Waiting'}</span>`}</div>${d?.comment?`<div class="stage-comment">“${esc(d.comment)}”<div class="record-sub">${date(d.at)}</div></div>`:''}</div>`}).join('');
 if(canActOnReview(r))html+=`<div class="decision-box"><h3>Your decision</h3><p class="form-hint" style="margin:7px 0 14px">Review the record and its connections. Your decision and note become part of its history.</p><div id="decision-error"></div><div class="field" style="margin:0"><label for="decision-comment">Review note <span class="muted" style="font-weight:400">· Required for return or rejection</span></label><textarea id="decision-comment" placeholder="What should the maker know?">${esc(reviewNotes[reviewNoteKey(r)]||'')}</textarea></div><div class="decision-actions">${btn('Approve','decide','check','primary','data-decision="approve"')}${btn('Request changes','decide','edit','','data-decision="return"')}${btn('Reject','decide','close','danger','data-decision="reject"')}</div></div>`;
 else if(r.status==='In review')html+=note(user===r.owner?'You created this request. Its assigned reviewers must make the approval decisions.':actor().role==='Auditor'?'Audit access is read-only. All decisions remain visible as this request progresses.':'This request is waiting for '+nextReviewers(r).map(id=>P(id).name).join(' and ')+'.','amber','lock');
 else if(['Draft','Changes requested'].includes(r.status))html+=note('The maker can edit this draft and submit it for a fresh review. Earlier decisions will not carry over.','','edit');
 if(r.submittedRefs&&drawer?.tab!=='approval')html+=`<div class="section-heading">References captured at submission</div>${Object.values(r.submittedRefs).map(s=>`<div class="unmatched">${esc(s.name)} · ${esc(s.code)} · approved version ${s.version}</div>`).join('')}`;return html;}
function readable(v){if(v==null)return '—';if(typeof v==='object'){if(Array.isArray(v))return v.map(readable).join(', ');return Object.entries(v).map(([k,val])=>`${TYPES[k]?.short||k}: ${find(data,val)?.name||readable(val)}`).join(' · ');}return String(v)}
function historyView(r){return `<div class="between" style="margin-bottom:23px"><span class="small muted">Every step, from the first draft.</span><span class="tag">${r.history.length} events</span></div>${[...r.history].sort((a,b)=>b.at.localeCompare(a.at)).map(e=>`<div class="timeline-item">${av(e.actor)}<div class="timeline-copy"><h4>${esc(e.action)} <span class="tiny muted" style="font-weight:400">· v${e.version}</span></h4><p>${esc(e.detail)}</p>${(e.changes||[]).map(c=>`<div class="diff"><strong>${esc(c.field)}</strong><del>− ${esc(readable(c.before))}</del><ins>+ ${esc(readable(c.after))}</ins></div>`).join('')}<time>${P(e.actor).name} · ${date(e.at)} IST</time></div></div>`).join('')}`}
function startCreate(type=null,parent=null,existing=null){if(wizard)rememberWizard();if(!can('create')){toast('Select your Maker authority to create or edit records.');return;}focusBefore=document.activeElement;drawer=null;const r=existing?find(data,existing):null;if(existing&&scratches[existing]&&(scratches[existing].ownerId||'maker')===user){wizard=structuredClone(scratches[existing]);renderWizard();return;}wizard={step:type||r?2:1,type:type||r?.type||null,existing,error:'',values:r?structuredClone(r):{name:'',description:'',region:'India',channel:'Digital',segment:'Premium',category:'Everyday',refs:{program:ui.program},value:'',rule:{field:'segment',value:'Premium',key:'Support tier',output:'Priority',priority:10}}};if(parent){const p=find(data,parent);wizard.values.refs={...wizard.values.refs,...active(p).refs,[p.type]:p.id};}wizard.scratchId=existing||crypto.randomUUID();renderWizard();}
function field(label,name,value='',options={}){const id='f-'+name;return `<div class="field"><label for="${id}">${label}${options.required?' <span style="color:#aa85b3">*</span>':''}</label>${options.select?`<select id="${id}" name="${name}" ${options.change?`data-change="${options.change}"`:''}><option value="">Select ${label.toLowerCase()}…</option>${options.select.map(o=>`<option value="${esc(o.value??o)}" ${(o.value??o)===value?'selected':''}>${esc(o.label??o)}</option>`).join('')}</select>`:options.textarea?`<textarea id="${id}" name="${name}" placeholder="${esc(options.placeholder||'Add a little context…')}">${esc(value)}</textarea>`:`<input id="${id}" name="${name}" value="${esc(value)}" type="${options.type||'text'}" ${options.type==='number'?'min="0" max="100"':''} placeholder="${esc(options.placeholder||'')}" ${options.required?'required':''}>`}${options.hint?`<small>${options.hint}</small>`:''}</div>`}
function collectWizard(){const form=document.getElementById('entity-form');if(!form)return;const fd=new FormData(form),v=wizard.values;for(const [key,value]of fd){if(key.startsWith('ref_'))v.refs[key.slice(4)]=value;else if(key.startsWith('rule_')){v.rule||={};v.rule[key.slice(5)]=key==='rule_priority'?Number(value):value;}else v[key]=value;}}
function wizardInput(){const v=wizard.values,t=wizard.type;return {type:t,name:v.name.trim(),description:v.description,refs:Object.fromEntries(TYPES[t].deps.map(k=>[k,v.refs[k]||''])),region:v.region,channel:v.channel,segment:v.segment,category:v.category,...(['bin','ace','cpc'].includes(t)?{value:v.value}:{}),...(t==='attribute'?{rule:v.rule}:{})};}
function renderWizard(){const w=wizard,v=w.values,t=w.type;let body='';if(w.step===1){body=`<p class="form-hint">Choose what you’d like to create. We’ll guide you through the connections and review.</p>${['Partner setup','Products & releases','Shared configurations'].map(g=>`<div class="eyebrow group-label">${g}</div><div class="type-grid">${Object.entries(TYPES).filter(([,x])=>x.group===g).map(([k,x])=>`<button class="type-choice" data-action="wizard-type" data-type="${k}">${ti(k)}<h3>${x.label}</h3><p>${x.hint}</p></button>`).join('')}</div>`).join('')}`;}
 else if(w.step===2){const current=find(data,w.existing);body=`${current?.status==='Changes requested'?note('<strong>Reviewer feedback</strong><br>'+esc(current.history.find(e=>e.action==='Changes requested')?.detail||'Review the decision history before resubmitting.'),'amber','edit'):''}${w.error?`<div class="error">${esc(w.error)}</div>`:''}<div class="flex gap12">${ti(t)}<div><h3>${TYPES[t].label}</h3><p class="small muted" style="margin-top:3px">${TYPES[t].hint}</p></div></div><div class="divider"></div><form id="entity-form">${field('Name','name',v.name,{required:true,placeholder:'Give this '+TYPES[t].short.toLowerCase()+' a clear name'})}${field('Description','description',v.description,{textarea:true})}${TYPES[t].deps.length?`<div class="section-heading">Connect to approved records</div>${note('Each parent can support multiple children. Choose an existing parent, even if it already has connections.','','link')}${TYPES[t].deps.map(dep=>{const opts=eligible(data,dep,v.refs.program);return field(TYPES[dep].label,'ref_'+dep,v.refs[dep],{required:true,select:opts.map(r=>({value:r.id,label:active(r).name+' · '+r.code})),change:'wizard-parent',hint:opts.length?dep==='brand'||dep==='base'||dep==='variant'?'Filtered to the selected program.':'Only approved versions are available.':'No approved '+TYPES[dep].plural.toLowerCase()+' available'+(['brand','base','variant'].includes(dep)?' for this program':'')+'. Save a draft and approve the parent first.'})}).join('')}`:''}<div class="form-row">${field('Region','region',v.region,{select:['India','United Kingdom','Singapore','Global']})}${field('Channel','channel',v.channel,{select:['Digital','Branch','All channels']})}</div>${t==='release'?`<div class="form-row">${field('Segment','segment',v.segment,{select:['Premium','Standard','Student']})}${field('Category','category',v.category,{select:['Everyday','Regional','Travel','Enterprise']})}</div>`:''}${['bin','ace','cpc'].includes(t)?field(t==='bin'?'BIN number':'Configuration value','value',v.value,{required:true,placeholder:t==='bin'?'6 or 8 digits':'Add the configuration value',hint:t==='bin'?'BINs are stored as text to preserve leading zeros.':t==='ace'?'For this demo, enter a descriptive comma-separated option list.':'Use your organisation’s CPC identifier or value.'}):''}${t==='attribute'?`<div class="section-heading">Matching rule</div><div class="form-row">${field('Release parameter','rule_field',v.rule?.field,{required:true,select:['segment','channel','region','category']})}${field('Equals','rule_value',v.rule?.value,{required:true,placeholder:'e.g. Premium'})}</div><div class="form-row">${field('Attribute name','rule_key',v.rule?.key,{required:true})}${field('Attribute value','rule_output',v.rule?.output,{required:true})}</div>${field('Priority','rule_priority',v.rule?.priority,{type:'number',hint:'0–100. A higher number wins when rules set the same attribute. Equal-priority conflicting values block the release.'})}`:''}</form>`;}
 else {const input=wizardInput(),candidate={...(find(data,wizard.existing)||{}),...input,owner:user,review:data.policies[t]};const reasons=blockers(data,candidate);body=`${note('One last look. Submitting locks this version for review. You can follow every decision from the record’s history.','','shield')}<h2 style="margin-bottom:8px">${esc(input.name||'Untitled '+TYPES[t].short.toLowerCase())}</h2><p class="form-hint">${esc(input.description||TYPES[t].hint)}</p>${Object.entries(input.refs).map(([type,id])=>{const r=find(data,id);return `<div class="ref-card">${ti(type)}<div><div class="ref-label">${TYPES[type].label}</div><div class="ref-name">${r?esc(active(r).name):'Not selected'}</div></div>${r?badge(live(r)?'Approved':r.status):''}</div>`}).join('')}<div class="section-heading">Approval route</div><div class="stage-card">${reviewRoute({...candidate,status:'Draft',review:{...candidate.review,decisions:{}}})}<p class="form-hint" style="margin:15px 0 0">${candidate.review.mode==='parallel'?'Parallel · All selected reviewers must approve.':'Sequential · Reviewers act in the order shown.'}</p></div>${t==='release'?`<div class="section-heading">Attribute match preview</div>${attributePreview(input)}`:''}${t==='attribute'?`<div class="attribute-match"><div class="strong small">When ${esc(input.rule.field)} equals “${esc(input.rule.value)}”</div><div class="why">Apply ${esc(input.rule.key)} = ${esc(input.rule.output)} · Priority ${input.rule.priority}</div></div>`:''}${reasons.length?`<div class="error"><strong>Before you submit</strong><br>${reasons.map(esc).join('<br>')}</div>`:note('All required parent records are approved. This request is ready for review.','green','circlecheck')}${w.error?`<div class="error">${esc(w.error)}</div>`:''}`;}
 mountOverlay(`<div class="overlay" data-overlay="true"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="wizard-title"><div class="drawer-head"><div><div class="eyebrow">${w.existing?'CONTINUE YOUR WORK':'A NEW CONNECTION'}</div><h2 id="wizard-title">${t?(w.existing?'Edit ':'Create ')+TYPES[t].label.toLowerCase():'Create a record'}</h2><p class="small muted">${w.step===1?'Choose the entity you want to create.':'Your unfinished form is saved in this browser.'}</p></div><button class="iconbtn" data-action="close" aria-label="Close creation form">${I('close')}</button></div><div class="stepper">${['Choose entity','Add details','Review & submit'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${w.step===i+1?'active':w.step>i+1?'done':''}"><span>${w.step>i+1?'✓':i+1}</span>${s}</div>`).join('')}</div><div class="drawer-main">${body}</div><div class="drawer-footer"><div class="flex gap8">${w.step>1?btn('Back','wizard-back','','sm'):btn('Cancel','close')}${w.step>1?textbtn('Discard form','discard-form',''):''}</div><div class="flex gap8">${w.step>1?btn('Save draft','wizard-save','edit'):''}${w.step===2?btn('Review details','wizard-next','arrow','primary'):w.step===3?btn('Submit for approval','wizard-submit','circlecheck','primary'):''}</div></div></section></div>`);}
function help(){focusBefore=document.activeElement;drawer=null;wizard=null;mountOverlay(`<div class="overlay" data-overlay="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="drawer-head"><div><div class="eyebrow">A QUICK WALKTHROUGH</div><h2 id="help-title">A clear path, for everyone.</h2></div><button class="iconbtn" data-action="close" aria-label="Close help">${I('close')}</button></div><div class="modal-content">${[['Make the connection','With Maker authority, create an entity, choose its approved parents, and preview the approval route. A parent can have many child records.'],['Give it a second look','Sign in with a checker account and select Checker authority. Sequential reviews unlock in order. Parallel reviews can happen together; everyone selected must approve.'],['Keep the story intact','An Auditor can inspect every record, relationship and decision. Each record has a History tab with actors, timestamps and field changes.'],['Build on what’s approved','Create another child from a parent’s details. Proposing a change keeps the approved version active while the new version is reviewed.'],['Connect shared foundations','BIN, ACE and CPC records are standalone. Brand mappings have their own approval. Attribute rules match release parameters and preserve a submission snapshot.']].map(([title,copy],i)=>`<div class="help-step"><span class="help-number">${i+1}</span><div><h3>${title}</h3><p>${copy}</p></div></div>`).join('')}${note('This is an interactive UI prototype. Demo login, role permissions and audit persistence run in this browser. Production authentication, authorisation and immutable storage require a backend.','','info')}</div><div class="drawer-footer"><span class="tiny muted">Designed for operations teams.</span>${btn('Let’s explore','close','arrow','primary')}</div></section></div>`);}

function bindEvents(){
 // Expiry is handled before any page or overlay action, including keyboard input.
 for(const eventName of ['click','change','input','submit','keydown'])document.addEventListener(eventName,e=>{
  if(!expireSession())return;
  e.preventDefault();e.stopImmediatePropagation();render();
  requestAnimationFrame(()=>document.getElementById('login-password')?.focus());
 },true);
 document.addEventListener('click',e=>{if(e.target.matches('[data-overlay]')){const form=!!wizard;closeOverlay();if(form)render();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,type=b.dataset.type;
 try{
 const editActions=['create','create-child','edit-record','amend','resume-form','discard-form','wizard-type','wizard-back','wizard-next','wizard-save','wizard-submit'];
 if(editActions.includes(a))requirePermission(authSession,'create');
 if(a==='decide')requirePermission(authSession,'review');
 if(['export-audit','export-records'].includes(a))requirePermission(authSession,'export');
 if(!activeAuthority(authSession)&&!['demo-username','toggle-password','authority-pick','enter-authority','signout'].includes(a))return;
 if(a==='nav'){goto(b.dataset.page);return;}
 if(a==='demo-username'){const input=document.getElementById('login-username');if(input){input.value=id;authUI.username=id;document.getElementById('login-password')?.focus();}return;}
 if(a==='toggle-password'){const input=document.getElementById('login-password'),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password');b.setAttribute('aria-pressed',String(show));return;}
 if(a==='authority-pick'){if(!authSession?.authorities.some(x=>x.id===id))return;authUI.selectedId=id;authUI.error='';render();return;}
 if(a==='enter-authority'){enterAuthority();return;}
 if(a==='signout'){signOut();return;}
 if(a==='roles'){if(!activeAuthority(authSession))return;ui.roleMenu=!ui.roleMenu;render();return;}
 if(a==='change-authority'){closeOverlay();authUI.selectedId=authSession.activeAuthorityId;authSession={...authSession,activeAuthorityId:null};ui.roleMenu=false;saveSession();render();window.scrollTo(0,0);return;}
 if(a==='mobile'){document.getElementById('sidebar')?.classList.toggle('mobile-open');return;}
 if(a==='close'){const unfinished=!!wizard;closeOverlay();if(unfinished){render();toast('Your unfinished form is saved. Resume it from My work.');}return;}
 if(a==='record'){openRecord(id,b.dataset.tab||'overview');return;}
 if(a==='captured-record'){const target=find(data,id),version=Number(b.dataset.version);openRecord(id,target?.published?.version===version?'active':'overview');if(target?.version!==version&&target?.published?.version!==version){drawer.snapshotNotice='This link shows the current record. The request captured version '+version+', which is no longer available as a full historical record in this prototype. Its captured values remain in the review evidence.';renderDrawer();}return;}
 if(a==='record-back'){captureReviewNote();drawer=recordTrail.pop();renderDrawer();return;}
 if(a==='detail-tab'){captureReviewNote();drawer.tab=id;renderDrawer();return;}
 if(a==='resume-form'){if((scratches[id]?.ownerId||'maker')!==user)throw Error('This unfinished form belongs to another user.');wizard=structuredClone(scratches[id]);drawer=null;renderWizard();return;}
 if(a==='discard-form'){forgetWizard();wizard=null;closeOverlay();render();toast('Unsubmitted form discarded. Saved records are unchanged.');return;}
 if(a==='create'){startCreate(type);return;}
 if(a==='create-child'){startCreate(type,b.dataset.parent);return;}
 if(a==='edit-record'){startCreate(null,null,id);return;}
 if(a==='amend'){amend(data,id,user);persist();render();startCreate(null,null,id);toast('Change proposed. The approved version remains active.');return;}
 if(a==='browse-type'){goto('records',{type,status:'all'});return;}
 if(a==='record-audit'){goto('audit',{auditRecord:id,auditAction:'all',auditPerson:'all'});return;}
 if(a==='clear-audit'){ui.auditRecord='';render();return;}
 if(a==='dashboard-tab'){ui.tab=id;render();return;}
 if(a==='review-tab'){ui.reviewTab=id;render();return;}
 if(a==='map-view'){ui.mapView=id;render();return;}
 if(a==='explore-entity'||a==='trace-entity'){if(ui.mapFocus&&ui.mapFocus!==id)ui.mapTrail.push(ui.mapFocus);ui.mapFocus=id;if(a==='trace-entity')ui.mapView='map';closeOverlay();render();return;}
 if(a==='map-back'){ui.mapFocus=ui.mapTrail.pop()||'prg1';render();return;}
 if(a==='work-tab'){ui.workTab=id;render();return;}
 if(a==='open-program'){goto('setup',{program:id});return;}
 if(a==='program-map'){goto('map',{mapFocus:id,mapProgram:id,mapView:'map',mapTrail:[]});return;}
 if(a==='clear-map-focus'){ui.mapFocus='';render();return;}
 if(a==='clear-map-search'){ui.mapQ='';ui.mapType='all';render();return;}
 if(a==='map-select'){ui.mapId=id;render();if(window.innerWidth<=980)openMapGroup(id);return;}
 if(a==='map-group'){openMapGroup(id);return;}
 if(a==='zoom-in'||a==='zoom-out'||a==='zoom-reset'){ui.zoom=a==='zoom-reset'?1:Math.max(.5,Math.min(1.4,ui.zoom+(a==='zoom-in'?.1:-.1)));render();return;}
 if(a==='help'){help();return;}
 if(a==='wizard-type'){wizard.type=type;wizard.step=2;wizard.error='';renderWizard();return;}
 if(a==='wizard-back'){collectWizard();if(wizard.existing&&wizard.step===2){openRecord(wizard.existing);return;}wizard.step--;wizard.error='';renderWizard();return;}
 if(a==='wizard-next'){collectWizard();if(!wizard.values.name.trim()){wizard.error='Add a clear name before continuing.';renderWizard();return;}wizard.step=3;wizard.error='';renderWizard();return;}
 if(a==='wizard-save'||a==='wizard-submit'){
   collectWizard();const input=wizardInput();if(!input.name){wizard.error='Add a name so you can find this draft later.';renderWizard();return;}
   if(a==='wizard-submit'){const reasons=blockers(data,{...(find(data,wizard.existing)||{}),...input,owner:user,review:data.policies[input.type]});if(reasons.length){wizard.error=reasons.join(' ');renderWizard();return;}}
   const r=saveDraft(data,input,user,wizard.existing);wizard.existing=r.id;if(a==='wizard-submit')submit(data,r.id,user);persist();forgetWizard();wizard=null;closeOverlay();render();openRecord(r.id,a==='wizard-submit'?'approval':'overview');toast(a==='wizard-submit'?'Submitted. Your reviewers can take it from here.':'Draft saved. Pick up where you left off.');return;
 }
 if(a==='decide'){const r=find(data,drawer.id);const comment=document.getElementById('decision-comment')?.value||reviewNotes[reviewNoteKey(r)]||'';try{decide(data,r.id,user,b.dataset.decision,comment);delete reviewNotes[reviewNoteKey(r)];storeNotes();persist();render();renderDrawer();toast(r.status==='Approved'?'All reviews complete. This version is now approved.':b.dataset.decision==='approve'?'Decision recorded. The next reviewer can continue.':b.dataset.decision==='return'?'Returned to the maker with your note.':'Request rejected. Your reason is in the history.');}catch(err){document.getElementById('decision-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}return;}
 if(a==='export-audit'){downloadCSV('relay-operations-audit.csv',['Timestamp (UTC)','Actor','Action','Record','Version','Detail'],filteredEvents().map(e=>[e.at,P(e.actor).name,e.action,e.recordName,e.version||'',e.detail]));return;}
 if(a==='export-records'){const rows=data.records.filter(r=>(ui.type==='all'||r.type===ui.type)&&(ui.status==='all'||r.status===ui.status)&&(!ui.q||(r.name+' '+r.code+' '+TYPES[r.type].label).toLowerCase().includes(ui.q.toLowerCase())));downloadCSV('relay-operations-records.csv',['Record ID','Name','Entity type','Status','Version','Program','Updated (UTC)'],rows.map(r=>[r.code,r.name,TYPES[r.type].label,r.status,r.version,find(data,r.refs.program)?.name||'',r.updatedAt]));return;}
 }catch(err){toast(err.message||'Something needs another look.');}
 });
 document.addEventListener('change',e=>{const el=e.target,c=el.dataset.change;if(el.closest('#entity-form'))rememberWizard();if(!c)return;if(c==='select-authority'){if(authSession?.authorities.some(a=>a.id===el.value)){authUI.selectedId=el.value;authUI.error='';render();requestAnimationFrame(()=>document.querySelector('input[name=authority]:checked')?.focus());}return;}if(c==='map-active'){ui.mapActiveOnly=el.checked;render();return;}
 if(c==='wizard-parent'){collectWizard();if(el.name==='ref_program'){for(const dep of ['brand','base','variant']){const r=find(data,wizard.values.refs[dep]);if(r&&active(r).refs.program!==el.value)delete wizard.values.refs[dep];}}wizard.error='';rememberWizard();renderWizard();return;}
 if(c==='policy-mode'||c==='policy-reviewer'){if(!can('policy')){render();return;}const t=el.dataset.type,p=data.policies[t],before=structuredClone(p);if(c==='policy-mode')p.mode=el.value;else{if(el.checked){p.reviewers.push(el.value);p.reviewers.sort((a,b)=>PEOPLE.findIndex(x=>x.id===a)-PEOPLE.findIndex(x=>x.id===b));}else if(p.reviewers.length===1){toast('Keep at least one reviewer assigned.');render();return;}else p.reviewers=p.reviewers.filter(id=>id!==el.value);}data.events.unshift({id:crypto.randomUUID(),action:'Policy updated',actor:user,at:new Date().toISOString(),recordName:TYPES[t].label+' approval policy',type:t,detail:TYPES[t].label+': '+p.mode+' review · '+p.reviewers.map(id=>P(id).name).join(', ')+'. Applies to new or resubmitted drafts.',changes:[{field:'Approval policy',before,after:structuredClone(p)}]});persist();render();toast('Approval policy saved. Active reviews keep their current route.');return;}
 ui[c]=el.value;if(c==='mapProgram'){ui.mapFocus=el.value==='all'?ui.mapFocus:el.value;ui.mapTrail=[];}if(c==='program'){ui.mapId=el.value;ui.zoom=1;}render();
 });
 document.addEventListener('input',e=>{if(e.target.id==='decision-comment'){captureReviewNote();return;}if(e.target.closest('#entity-form')){rememberWizard();return;}if(!['search','map-search'].includes(e.target.dataset.input))return;const id=e.target.id,pos=e.target.selectionStart;if(e.target.dataset.input==='map-search'){ui.mapQ=e.target.value;}else ui.q=e.target.value;render();const input=document.getElementById(id);input?.focus();input?.setSelectionRange(pos,pos);});
 document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='sign-in-form'){signIn(e.target);return;}if(e.target.id==='global-search'){const q=document.getElementById('global-q').value;goto('records',{q,type:'all',status:'all'});}});
 document.addEventListener('keydown',e=>{if(e.target.id==='login-password'){const caps=document.getElementById('caps-warning');if(caps)caps.hidden=!e.getModifierState('CapsLock');}if(e.key==='Escape'){if(drawer||wizard||document.querySelector('.modal')){const form=!!wizard;closeOverlay();if(form)render();}else if(ui.roleMenu){ui.roleMenu=false;render();}document.getElementById('sidebar')?.classList.remove('mobile-open');}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-q')?.focus();}if(e.key==='Tab'&&document.querySelector('.overlay')){const nodes=[...document.querySelectorAll('.overlay button:not(:disabled), .overlay input:not(:disabled), .overlay textarea:not(:disabled), .overlay select:not(:disabled), .overlay a[href]')].filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
}
function downloadCSV(name,headers,rows){const escape=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv=[headers,...rows].map(row=>row.map(escape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded.');}
