function openMapGroup(id){const r=find(data,id),group=groupRecords(id);focusBefore=document.activeElement;drawer=null;wizard=null;mountOverlay(`<div class="overlay" data-overlay="true"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="group-title"><div class="drawer-head"><div><div class="eyebrow">EXPLORE THE CONNECTIONS</div><h2 id="group-title">${TYPES[r.type].plural}</h2><p class="small muted">${group.length} records · Each has its own children and approval history.</p></div><button class="iconbtn" data-action="close" aria-label="Close connections">${I('close')}</button></div><div class="drawer-main">${group.map(x=>`<button class="ref-card" data-action="explore-entity" data-id="${x.id}">${ti(x.type)}<span><span class="ref-name">${esc(x.name)}</span><span class="ref-label" style="display:block;margin-top:5px">${data.records.filter(c=>Object.values(c.refs).includes(x.id)).length} downstream connections</span></span>${badge(x)}</button>`).join('')}${note('A single parent can have many children. Open a record to see every connection or create another.','','map')}</div><div class="drawer-footer"><span class="tiny muted">${group.length} records in this group</span>${can('create')?btn('Create another','create','plus','primary',`data-type="${r.type}"`):btn('Close','close')}</div></section></div>`);}
