const I=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[n]||PATHS.layers}</svg>`;
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='relay-design-v1';let data;
try{data=JSON.parse(localStorage.getItem(KEY));if(data?.schema!==1)data=null;}catch{}
data ||= seed();
let authSession=null;
try{authSession=restoreSession(sessionStorage.getItem(SESSION_KEY));}catch{}
let user=authSession?.user.id||null;
const authUI={username:authSession?.user.username||'',selectedId:authSession?.authorities.length===1?authSession.authorities[0].id:'',error:'',pending:false};
let authAttempt=0;
const can=permission=>allowed(authSession,permission);
const canActOnReview=r=>can('review')&&canReview(r,user);
function saveSession(){try{if(authSession)sessionStorage.setItem(SESSION_KEY,serializeSession(authSession));else sessionStorage.removeItem(SESSION_KEY);}catch{}}
function signOut(){authAttempt++;closeOverlay();authSession=null;user=null;authUI.error='';authUI.pending=false;authUI.selectedId='';authUI.username='';ui.roleMenu=false;ui.workTab='';saveSession();render();window.scrollTo(0,0);}
function expireSession(){
 if(!authSession||authSession.expiresAt>Date.now())return false;
 // Preserve in-progress work under the original identity before clearing access.
 authAttempt++;closeOverlay();authSession=null;user=null;
 authUI.error='Your session has expired. Sign in again.';authUI.pending=false;authUI.selectedId='';
 ui.roleMenu=false;ui.workTab='';saveSession();return true;
}
async function signIn(form){
 if(authUI.pending)return;
 const username=form.elements.username.value,password=form.elements.password.value;
 authUI.username=username;authUI.error='';authUI.pending=true;const attempt=++authAttempt;render();
 await new Promise(resolve=>setTimeout(resolve,450));
 if(attempt!==authAttempt)return;
 try{const response=authenticateDemo(username,password);authSession=startSession(response);user=authSession.user.id;authUI.selectedId=response.authorities.length===1?response.authorities[0].id:'';saveSession();}
 catch(error){authSession=null;user=null;authUI.error=error.message;saveSession();}
 finally{authUI.pending=false;render();requestAnimationFrame(()=>document.getElementById(authSession?'authority-heading':'login-password')?.focus());}
}
function enterAuthority(){
 try{authSession=selectAuthority(authSession,authUI.selectedId);user=authSession.user.id;saveSession();authUI.error='';ui.page='overview';ui.roleMenu=false;ui.workTab='';ui.reviewTab=actorRoleDefault();ui.q='';history.replaceState(null,'','#overview');render();window.scrollTo(0,0);toast('Signed in as '+authSession.user.name+' · '+activeAuthority(authSession).label);}
 catch(error){authUI.error=error.message;render();}
}

