const ago=t=>{const n=Math.max(0,(Date.now()-new Date(t))/3600000);return n<1?'Just now':n<24?Math.floor(n)+'h ago':Math.floor(n/24)+'d ago'};
const date=t=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(new Date(t));
