function programOptions(all=false,value=ui.program){return `${all?`<option value="all" ${value==='all'?'selected':''}>All partner programs</option>`:''}${data.records.filter(r=>r.type==='program').map(r=>`<option value="${r.id}" ${value===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}`}
const recordButton=(r,label)=>`<button class="linkname" data-action="record" data-id="${r.id}">${esc(label||r.name)}</button>`;
const recordCount=(t,status)=>data.records.filter(r=>(!t||r.type===t)&&(!status||r.status===status)).length;
